(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zx-sj-prepa-sp-j5-idesfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zx-sj-prepa-sp-j5-idesfm\",\n \"titre\": \"Préparation D.E (J) · J5 Santé publique IDE/SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 58,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n   \"sha256\": \"cfef47fa50d1b8029734184173064280cf7273a669584d71619e0dc62d9fb1a8\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Santé publique · Prépa D.E J5 (IDE/SFM)\",\n     \"slug\": \"prepa-sp-j5-idesfm\",\n     \"pages\": \"\",\n     \"count\": 58,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Santé publique\",\n     \"source\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__0\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le COGES est composé exclusivement d'agents de santé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le COGES compte 10 à 20 représentants des communautés villageoises de l'aire sanitaire. En dehors de l'infirmier, de la sage-femme ou du travailleur social, les autres membres viennent de la communauté. Il n'est donc pas composé uniquement d'agents de santé.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », III\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__1\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le décret N°93-218 du 03 février 1993 fixe les règles de gestion des formations sanitaires rurales. Le COGES comprend entre 10 et 20 membres\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les règles de gestion des formations sanitaires rurales sont fixées par le décret n° 93-218 du 03 février 1993. Son article 3 prévoit un comité de 10 à 20 personnes.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », I et III\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__2\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les membres du COGES sont nommés pour un mandat de cinq ans non renouvelables\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon l'article 3 du décret, les membres sont désignés pour trois ans, renouvelables. « Cinq ans » et « non renouvelables » sont donc tous deux faux.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », IV\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__3\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les ASC et les AT font partie d'office du COGES\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les agents de santé communautaire (ASC) et les accoucheuses traditionnelles (AT) font partie d'office du COGES, à cause de leur rôle de relais communautaire.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », III (Nota Bene)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__4\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La participation aux activités du COGES est rémunérée\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La participation aux activités du COGES est du bénévolat.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », III (Nota Bene)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__5\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un membre du COGES doit résider dans un village desservi par le centre de santé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Premier critère pour être membre : résider en permanence dans un village desservi par le centre de santé. Il faut aussi être de bonne moralité et avoir une activité génératrice de revenu.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », V\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__6\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le COGES élabore le budget semestriel du centre de santé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la gestion financière, le COGES « élabore le budget semestriel ». Ce budget est fait tous les six mois, en même temps que le monitorage.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », 6.1.1 ; Cours Santé publique L3 (DOC-20260911-WA0542), « Budgétisation des ressources propres d'un ESPC », III\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__7\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le COGES ne joue aucun rôle dans la gestion des ressources humaines\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le COGES a un rôle dans la gestion des ressources humaines. Il veille à la présence du personnel de santé et de soutien, à la qualité de la communication entre consultants et personnel, et au savoir-être du personnel.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », 6.1.2\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__8\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le COGES veille à la disponibilité des médicaments essentiels et des vaccins.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la gestion du matériel, des médicaments et du local, le COGES veille à la disponibilité des médicaments essentiels et des vaccins.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », 6.1.3\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__9\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le COGES peut promouvoir l'acceptabilité des services offerts à la population\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"En dehors du centre, le COGES doit promouvoir l'acceptabilité des services offerts à la population. Il fait aussi connaître les activités du centre et promeut la participation financière.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », 6.2\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__10\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le responsable de la gestion financière tient le livret de caisse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le livret de caisse fait partie des outils du responsable de la gestion financière. Il y note les recettes et les dépenses du centre.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », 7.2 et 8.2\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__11\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le président du COGES coordonne les activités du comité\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Parmi les fonctions du président : coordonner les activités du COGES. Il ouvre aussi le compte, convoque les réunions et donne son accord pour les retraits.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », 8.1\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__12\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les dons et legs constituent une source de revenus du COGES.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le COGES a trois sources de revenus : les actes de santé, la vente de certains documents (carnets, cartes) et les dons et legs.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », 9.1\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__13\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les dépenses liées à l'eau et à l'électricité peuvent être prises en charge par le COGES\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Selon l'article 7 du décret 93-218, les dépenses du COGES comprennent la consommation d'eau et d'électricité. Elles comprennent aussi les salaires du personnel non pris en charge par l'État, l'entretien et les fournitures.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », 9.2\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__14\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un indicateur est une variable quantitative ou qualitative mesurant un aspect d'une intervention\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours définit l'indicateur comme une variable quantitative ou qualitative simple qui mesure un aspect d'une intervention en santé, d'un programme ou d'un projet.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion de l'information sanitaire », I.1.1\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__15\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les données sont déjà des informations interprétées\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La donnée est la matière première (l'input) que l'on transforme. L'information est le résultat de cette transformation : la donnée placée dans un contexte significatif et utile. Une donnée n'est donc pas encore une information interprétée.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion de l'information sanitaire », I.1.2 et I.1.3\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__16\",\n       \"num\": \"21\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'information sanitaire est le résultat du traitement et de l'analyse des données\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'information est le résultat de la transformation des données en faits utiles pour les décideurs (traitement, analyse et interprétation).\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion de l'information sanitaire », I.1.3 et II\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__17\",\n       \"num\": \"22\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La collecte des données sanitaires consiste à enregistrer les données dans les registres et rapports\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La collecte consiste à enregistrer toutes les données sanitaires dans les registres d'activités, puis à les reporter dans les fiches de rapport mensuel ou annuel.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion de l'information sanitaire », II.2.1\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__18\",\n       \"num\": \"23\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le rapport mensuel des ESPC doit être transmis au district sanitaire au plus tard le 5 du mois suivant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le rapport mensuel de l'ESPC (rapport A) est transmis au CSE du district sanitaire au plus tard le 5 du mois suivant. Pour l'hôpital général, c'est le 10, et pour le CHR, le 15.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion de l'information sanitaire », II.2.3 (tableau) et IV\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__19\",\n       \"num\": \"24\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le taux de complétude mesure la proportion de rapports reçus parmi ceux attendus\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"TC = (rapports d'activités reçus par le responsable du CSE / rapports attendus) × 100. Le délai ne compte pas ; c'est le taux de promptitude qui en tient compte.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion de l'information sanitaire », II.2.3.2 ; Formules Santé publique harmonisées, chap. 8\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__20\",\n       \"num\": \"25\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La rétro-information correspond au retour des informations produites vers les niveaux inférieurs\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La rétro-information est le retour de l'information produite vers les structures des niveaux primaire et secondaire qui ont produit les données.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion de l'information sanitaire », II.2.8\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__21\",\n       \"num\": \"26\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une catastrophe est un événement dont les effets dépassent les capacités de réaction de la communauté\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Une catastrophe est un événement naturel ou causé par l'homme, aux effets négatifs importants, qui dépasse la capacité de réaction de la collectivité touchée. Une situation d'urgence, elle, reste gérable par la société.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion des catastrophes naturelles / épidémies », I.1.2 et III\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__22\",\n       \"num\": \"27\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le risque est indépendant du danger et de la vulnérabilité\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le risque est la probabilité de pertes après un événement défavorable, « vu le danger et la vulnérabilité ». Il dépend donc des deux.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion des catastrophes naturelles / épidémies », I.1.5\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__23\",\n       \"num\": \"28\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les tremblements de terre sont des catastrophes naturelles\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours cite parmi les catastrophes naturelles les cyclones, les tremblements de terre et le tsunami.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion des catastrophes naturelles / épidémies », IV\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__24\",\n       \"num\": \"29\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'un des rôles de l'infirmier en cas de catastrophe est de donner l'alerte\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le rôle principal de l'infirmier ou de la sage-femme est de donner l'alerte au directeur départemental de la santé le plus vite possible, pour que les secours soient organisés. Il apporte aussi un soutien psychologique à la communauté.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion des catastrophes naturelles / épidémies », VI\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__25\",\n       \"num\": \"30\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La supervision vise l'amélioration des compétences et du rendement du personnel\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La supervision vise l'amélioration de la compétence, de la qualité de service et du rendement du personnel en activité. Son but est d'améliorer en continu la performance du personnel.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « La supervision », II et III (tableau)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__26\",\n       \"num\": \"31\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La supervision est généralement une activité annoncée et périodique\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans le tableau qui compare la supervision aux autres fonctions, son moment est « annoncé et périodique ». L'inspection, elle, peut se faire à l'improviste.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « La supervision », III (tableau)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__27\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le but principal du COGES est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Sanctionner le personnel\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Associer la communauté à la gestion du centre de santé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Construire des hôpitaux universitaires\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Remplacer l'État\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Associer la communauté à la gestion du centre de santé\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le COGES est créé pour associer la communauté, comme membres actifs, à la gestion et au fonctionnement du centre de santé. Il ne sanctionne pas le personnel et ne remplace pas l'État.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », II\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__28\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La durée du mandat des membres du COGES est de\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1 an\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"2 ans\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3 ans renouvelables\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"5 ans\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 3 ans renouvelables\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Article 3 du décret 93-218 : les membres sont désignés pour trois ans, renouvelables.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », IV\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__29\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le bureau du COGES comprend\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Président, secrétaire, trésorier, un commissaire au compte\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Président, responsable financier, responsable administratif et technique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Président, maire, préfet\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Président et deux infirmiers\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Président, responsable financier, responsable administratif et technique\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le bureau compte trois membres : le président (membre communautaire), le responsable de la gestion financière (membre communautaire) et le responsable de la gestion administrative et technique (infirmier, sage-femme ou travailleur social).\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », III\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__30\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le responsable de la gestion financière est chargé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Des consultations médicales\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"De l'enregistrement des recettes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"De la vaccination\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"De la surveillance épidémiologique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. De l'enregistrement des recettes\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le responsable de la gestion financière recueille chaque jour les sommes collectées et les enregistre dans le livret de caisse. Il les verse ensuite à la banque. Les consultations et la vaccination relèvent des agents de santé.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Composition et fonctionnement du COGES d'un ESPC », 8.2\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__31\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un indicateur est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une donnée brute\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une opinion\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une variable permettant de mesurer un aspect d'une intervention\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Un rapport annuel\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Une variable permettant de mesurer un aspect d'une intervention\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'indicateur est une variable, quantitative ou qualitative, qui mesure un aspect d'une intervention, d'un programme ou d'un projet. Une donnée brute n'est que la matière première.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion de l'information sanitaire », I.1.1\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__32\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'information sanitaire est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une donnée non traitée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une donnée contextualisée et utile\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un registre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une fiche de consultation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Une donnée contextualisée et utile\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'information est la donnée « placée dans un contexte significatif et utile pour l'utilisateur final ». Une donnée non traitée n'est pas encore une information. Le registre et la fiche sont des outils de collecte.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion de l'information sanitaire », I.1.3\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__33\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La première étape du processus de génération de l'information sanitaire est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'analyse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'interprétation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La collecte\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La diffusion\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La collecte\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les étapes sont, dans l'ordre : collecte, compilation, transmission, traitement, analyse et interprétation, utilisation, diffusion, rétro-information. La collecte vient en premier.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion de l'information sanitaire », II\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__34\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le taux de promptitude est calculé à partir\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Des consultations\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Des rapports reçus dans le délai requis\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Des supervisions\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Des naissances\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Des rapports reçus dans le délai requis\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"TP = (rapports mensuels reçus dans le délai requis / rapports attendus) × 100.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion de l'information sanitaire », II.2.3.1 ; Formules Santé publique harmonisées, chap. 8\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__35\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La rétro-information est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une transmission ascendante\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une sanction administrative\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un retour des informations vers les producteurs des données\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une analyse statistique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Un retour des informations vers les producteurs des données\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La rétro-information est le retour de l'information produite vers les structures productrices des données. C'est un mouvement descendant, pas une transmission ascendante.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion de l'information sanitaire », II.2.8\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__36\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Selon l'OMS, le SIS sert à\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Construire des centres de santé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Fournir des renseignements sanitaires pour la prise de décision\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Recruter du personnel\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Payer les agents\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Fournir des renseignements sanitaires pour la prise de décision\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon l'OMS, le SIS fournit des renseignements et informations sanitaires pour surveiller l'état et les services de santé, et pour améliorer les décisions de gestion à tous les niveaux.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion de l'information sanitaire », I.1.5\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__37\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le niveau central de gestion des données sanitaires est représenté par\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'EPHR\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le District sanitaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La DIIS\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'ESPC\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La DIIS\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Au niveau central, la gestion des données sanitaires est assurée par la Direction de l'Information Sanitaire. L'ESPC et le district relèvent du niveau périphérique. Remarque : Le cours écrit « DIS » (Direction de l'Information Sanitaire) ; le sujet écrit « DIIS ».\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion de l'information sanitaire », III.3.4 et IV\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__38\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une catastrophe est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une urgence mineure\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un événement sans impact\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un événement dépassant la capacité de réaction de la communauté\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une simple vulnérabilité\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Un événement dépassant la capacité de réaction de la communauté\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Une catastrophe a des effets négatifs importants et dépasse la capacité de réaction de la collectivité touchée. Une situation d'urgence, elle, reste gérable.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Gestion des catastrophes naturelles / épidémies », I.1.2 et III\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__39\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le style de supervision adapté aux situations d'urgence est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Démocratique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Participatif\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Autocratique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Laisser-faire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Autocratique\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le style autocratique convient aux urgences, qui exigent une décision sans délai, et aux situations de blocage. Le style démocratique ou participatif s'applique à toutes les situations sauf l'urgence et le blocage.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « La supervision », IV.4.1.3 et 4.2.3\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__40\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La méthode directe de supervision repose sur\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'analyse documentaire uniquement\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'observation directe du personnel au travail\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le questionnaire administratif\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le rapport annuel\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. L'observation directe du personnel au travail\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Méthode directe : observer l'agent pendant qu'il exécute une tâche. La méthode indirecte, elle, passe par l'interrogatoire des usagers ou l'analyse des supports de données.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « La supervision », VI.6.1\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__41\",\n       \"num\": \"46\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les outils du superviseur figure\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La fiche d'observation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le carnet de vaccination\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le registre de consultation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La carte sanitaire nationale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La fiche d'observation\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les outils du superviseur sont : le classeur du superviseur, le classeur de la formation sanitaire, le cahier à problèmes, la fiche de synthèse et la fiche de supervision ou d'observation.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « La supervision », VIII\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__42\",\n       \"num\": \"47\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le style démocratique de supervision\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Empêche toute initiative\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Repose sur la participation des collaborateurs\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Est réservé aux urgences\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Exclut le dialogue\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Repose sur la participation des collaborateurs\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans le style démocratique ou participatif, le superviseur fait participer ses collaborateurs à la planification et encourage leurs initiatives. Il ne convient pas aux urgences.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « La supervision », IV.4.2\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__43\",\n       \"num\": \"48\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"L'accessibilité géographique (AG) est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"60 %.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"10 %.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"80 %.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"100 %.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 80 %.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"AG = population vivant dans le rayon d'accès / population cible × 100 = 6 400 / 8 000 × 100 = 80 %. Sur le semestre, on obtient le même résultat : 3 200 / 4 000 = 80 %. Remarque : Le cours retient un rayon de 5 km (OMS), mais le tableau des goulots cite 10 km pour les CSC. Le sujet donne directement les résidents à moins de 10 km.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Monitorage et évaluation de la couverture des activités », IV.4.3 ; Formules Santé publique harmonisées, chap. 6\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__44\",\n       \"num\": \"49\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"La population cible semestrielle est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"4 000 personnes.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"6400 personnes.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"2400 personnes.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1800 personnes.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 4 000 personnes.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La population cible du monitorage se calcule sur la période couverte. Pour 6 mois, on divise la population annuelle par 2 : 8 000 / 2 = 4 000 personnes.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Monitorage et évaluation de la couverture des activités », IV.4.1\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__45\",\n       \"num\": \"50\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"L'utilisation des services (US) est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"70 %.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"100 %.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"60 %.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"80 %.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 60 %.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"US = personnes ayant utilisé le service au moins une fois / PC du monitorage × 100 = 2 400 / 4 000 × 100 = 60 %.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Monitorage et évaluation de la couverture des activités », IV.4.4 ; Formules Santé publique harmonisées, chap. 6\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__46\",\n       \"num\": \"51\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"La couverture adéquate (CA) est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"45 %.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"85 %.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"65 %.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"90 %\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 45 %.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La CA compte ceux qui ont reçu la prestation en quantité requise (traitement reçu et payé) : 1 800 / 4 000 × 100 = 45 %.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Monitorage et évaluation de la couverture des activités », IV.4.5 ; Formules Santé publique harmonisées, chap. 6\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__47\",\n       \"num\": \"52\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"La couverture effective (CE) est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"37%\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3,7%\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"5,3 %\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"73%\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 37%\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La CE compte ceux qui ont reçu la prestation avec la qualité requise (directives nationales, médicaments non périmés) : 1 500 / 4 000 × 100 = 37,5 %. Le cours garde la partie entière sans arrondir, d'où 37 %. Le dossier avec un médicament périmé est exclu de la CE.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Monitorage et évaluation de la couverture des activités », IV.4.2 et 4.6\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__48\",\n       \"num\": \"53\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"Quel montant correspondent aux FR ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"100 000 F CFA.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"4000 000 F CFA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"400 000 F CFA.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1 400 000 F CFA.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 400 000 F CFA.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"FR = somme à la banque à la veille du monitorage − recettes du semestre déjà déposées = 1 000 000 − 600 000 = 400 000 F CFA. Les intérêts et agios sont déjà compris dans le solde : rien à ajouter.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Budgétisation des ressources propres d'un ESPC », V.5.1 ; Formules Santé publique harmonisées, chap. 7\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__49\",\n       \"num\": \"54\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"Quel montant correspond à la SAB\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"600 000 F CFA\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"400 000 F CFA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"80 000 F CFA\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"8 000 000 F CFA\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 600 000 F CFA\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours définit la SAB comme le total des recettes des six mois du monitorage. Le sujet indique 600 000 F CFA de recettes du semestre, ce qui correspond à la valeur retenue.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Budgétisation des ressources propres d'un ESPC », V.5.2 ; Formules Santé publique harmonisées, chap. 7\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__50\",\n       \"num\": \"55\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"Quel montant correspond aux dépenses de fonctionnement local ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"100 000 F CFA.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"400 000 F CFA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"600 000 F CFA.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"300 000 F CFA.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 300 000 F CFA.\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"DFL = SAB − DO. Avec SAB = RVME + RCAS = 1 000 000 F CFA et DO = 700 000 F CFA, on obtient DFL = 300 000 F CFA. Remarque : Ce calcul utilise SAB = 1 000 000 F CFA, et non les 600 000 F CFA retenus à la question 54.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Budgétisation des ressources propres d'un ESPC », V.5.4 ; Formules Santé publique harmonisées, chap. 7\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__51\",\n       \"num\": \"56\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"Le plafond de réparation de l'immeuble\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"40 000 F CFA.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"60 000 F CFA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"30 000 F CFA.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"10 000 F CFA.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 30 000 F CFA.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Les frais de réparation de l'immeuble ne doivent pas dépasser 10 % des DFL : 10 % × 300 000 = 30 000 F CFA.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Budgétisation des ressources propres d'un ESPC », V.5.4 ; Formules Santé publique harmonisées, chap. 7 (Im = 10 % × DFL)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__52\",\n       \"num\": \"57\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"Le plafond des imprévus\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"15 000 F CFA.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"150 000 F CFA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"30 000 F CFA.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"10 000 F CFA.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 15 000 F CFA.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les imprévus (frais bancaires, carburant d'urgence) ne doivent pas dépasser 5 % des DFL : 5 % × 300 000 = 15 000 F CFA.\\n\\nSource : Cours Santé publique L3 (DOC-20260911-WA0542), « Budgétisation des ressources propres d'un ESPC », V.5.4 ; Formules Santé publique harmonisées, chap. 7 (Imp = 5 % × DFL)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__53\",\n       \"num\": \"58\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"text\": \"Quel est le taux d'utilisation du mois écoulé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"10 %.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"20 %.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"80 %.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"90 %.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 90 %.\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"TU = doses administrées / doses sorties × 100 = 180 / 200 × 100 = 90 %.\\n\\nSource : Document révisé L2 2023-2024, « Gestion des vaccins et consommables » ; Formules Santé publique harmonisées, chap. 5\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__54\",\n       \"num\": \"59\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"text\": \"Quel est le taux de perte correspondant ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"5 %.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"10 %.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"20 %.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"90 %.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 10 %.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"TP = (doses sorties − doses administrées) / doses sorties × 100 = (200 − 180) / 200 × 100 = 10 %. On peut aussi faire TP = 100 − TU = 100 − 90 = 10 %.\\n\\nSource : Document révisé L2 2023-2024, « Gestion des vaccins et consommables » ; Formules Santé publique harmonisées, chap. 5\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__55\",\n       \"num\": \"60\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"text\": \"Quel facteur de perte découle de ce taux ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"0,90.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1,00.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Environ 1,11.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"2,00.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Environ 1,11.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"FP = 100 / (100 − TP) = 100 / 90 = 1,11. C'est aussi le facteur de perte du DTC-HepB-Hib (Penta) dans le tableau du cours.\\n\\nSource : Document révisé L2 2023-2024, « Gestion des vaccins et consommables » ; Formules Santé publique harmonisées, chap. 5\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__56\",\n       \"num\": \"61\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"text\": \"Quel est le besoin réel pour le mois suivant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"280 doses.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"400 doses.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"500 doses.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"520 doses.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 500 doses.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"SS = 25 % × BT = 0,25 × 400 = 100 doses. BR = BT + SS = 400 + 100 = 500 doses.\\n\\nSource : Document révisé L2 2023-2024, « Gestion des vaccins et consommables » ; Formules Santé publique harmonisées, chap. 5\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__57\",\n       \"num\": \"62\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"text\": \"Quelle quantité de doses faut-il commander, sous réserve du conditionnement en flacons ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"120.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"280.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"380.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"500.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 380.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"QC = BR − QS = 500 − 120 = 380 doses.\\n\\nSource : Document révisé L2 2023-2024, « Gestion des vaccins et consommables » ; Formules Santé publique harmonisées, chap. 5\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
